    scope = scope.new_child({
        Path: [],
        T: target,
        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope,
        CHILD_ERRORS: [],
        MODE: AUTO,
        MIN_MODE: AUTO,
        NO_PYFRAME: True,
    })

